// 商品リストから「未処理」の行だけを取り出し、1回の実行で作る件数を制限する。
// ここの数字を変えれば1日の生成件数を調整できる。
const MAX_PER_RUN = 3;

const rows = $input.all().map(item => item.json);

const pending = rows.filter(r => {
	const status = String(r['ステータス'] ?? '').trim();
	return status === '' || status === '未処理';
});

if (pending.length === 0) {
	// 対象がなければ空を返す。以降のノードは動かない。
	return [];
}

return pending.slice(0, MAX_PER_RUN).map(r => ({ json: r }));

// AIの回答（JSON文字列）を安全に読み取り、アフィリエイトリンクと広告表記をつけて
// スプレッドシートに書ける形に整える。

// 広告表記。ステマ規制（景品表示法の指定告示、2023年10月1日施行）への対応。
// ASPやSNSごとに求められる書き方が違うので、必ず自分の使うASPの規約も確認すること。
const AD_LABEL = 'PR / 広告を含みます';

function parseAiJson(text) {
	if (typeof text !== 'string') return null;
	// ```json ... ``` のコードフェンスを外す
	let t = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
	try {
		return JSON.parse(t);
	} catch (e) {
		// 前後に説明文がついている場合、最初の { から最後の } までを拾う
		const s = t.indexOf('{');
		const e2 = t.lastIndexOf('}');
		if (s !== -1 && e2 > s) {
			try { return JSON.parse(t.slice(s, e2 + 1)); } catch (e3) { return null; }
		}
		return null;
	}
}

const out = [];

for (let i = 0; i < $input.all().length; i++) {
	const item = $input.all()[i];
	// chainLlm は入力順に1件ずつ処理するので、同じ位置の商品データを取り出す。
	const sources = $('未処理を選ぶ').all();
	const source = (sources[i] ?? sources[sources.length - 1])?.json ?? {};

	// Basic LLM Chain の出力フィールド名はバージョンで変わることがあるため、
	// text / response / output の順に探す。
	const raw = item.json.text ?? item.json.response ?? item.json.output ?? '';
	const parsed = parseAiJson(raw);

	const title = parsed?.title ?? '';
	const bodyText = parsed?.body ?? (parsed ? '' : String(raw));
	const hashtags = Array.isArray(parsed?.hashtags) ? parsed.hashtags.join(' ') : (parsed?.hashtags ?? '');
	const aiNote = parsed?.note ?? '';

	const link = String(source['アフィリエイトリンク'] ?? '').trim();

	// 投稿用の本文を組み立てる。リンクが空なら差し込まず、確認事項として残す。
	const parts = [bodyText];
	if (link) parts.push(link);
	if (hashtags) parts.push(hashtags);
	parts.push(AD_LABEL);
	const fullText = parts.filter(Boolean).join('\n\n');

	// 人が確認すべき点をまとめる。空欄や失敗を黙って通さないため。
	const checks = [];
	if (!parsed) checks.push('AIの回答がJSONとして読めなかった。本文をそのまま入れてある');
	if (!link) checks.push('アフィリエイトリンクが空欄');
	if (!title) checks.push('タイトルが空');
	if (aiNote) checks.push('AIからの申し送り: ' + aiNote);

	out.push({
		json: {
			id: source.id ?? '',
			生成日時: new Date().toISOString(),
			商品名: source['商品名'] ?? '',
			ASP: source['ASP'] ?? '',
			タイトル案: title,
			本文: bodyText,
			ハッシュタグ: hashtags,
			投稿用テキスト: fullText,
			要確認: checks.join(' / '),
			ステータス: '下書き',
		},
	});
}

return out;

// 承認依頼メールの文面を1通ぶんだけ組み立てる。
// ここで1件にまとめるので、下書きが3件でもメールは1通。
const rows = $input.all().map(i => i.json);

const names = rows.map(r => r['商品名']).filter(Boolean);
const warnings = rows
	.filter(r => r['要確認'])
	.map(r => `- ${r['商品名']}: ${r['要確認']}`);

const 本文 = [
	`アフィリエイトの下書きが ${rows.length} 件できました。`,
	'',
	'【対象】',
	names.length ? names.map(n => `- ${n}`).join('\n') : '- なし',
	'',
	'【要確認】',
	warnings.length ? warnings.join('\n') : '- なし',
	'',
	'下書きシートで内容を確認してください。',
	'投稿は自動では行いません。確認後、手動で投稿してください。',
].join('\n');

return [{ json: { 件名: `アフィリエイト下書き ${rows.length}件（要確認 ${warnings.length}件）`, 本文 } }];
